@@ -1,17 +1,40 @@
-import { useEffect, useState } from 'react';
+import { useCallback, useEffect, useRef, useState } from 'react';

 type State = 'loading' | 'success' | 'error';

 export function AsyncPanel() {
   const [state, setState] = useState<State>('loading');
+  const timerRef = useRef<number | null>(null);
+
+  const schedule = useCallback((onDone: () => void) => {
+    if (timerRef.current !== null) {
+      window.clearTimeout(timerRef.current);
+    }
+    timerRef.current = window.setTimeout(() => {
+      timerRef.current = null;
+      onDone();
+    }, 120);
+  }, []);
+
+  const clearScheduled = useCallback(() => {
+    if (timerRef.current !== null) {
+      window.clearTimeout(timerRef.current);
+      timerRef.current = null;
+    }
+  }, []);

   useEffect(() => {
-    const timer = window.setTimeout(() => {
+    schedule(() => {
       const requested = new URLSearchParams(window.location.search).get('sync');
       setState(requested === 'error' ? 'error' : 'success');
-    }, 120);
-    return () => window.clearTimeout(timer);
-  }, []);
+    });
+    return clearScheduled;
+  }, [schedule, clearScheduled]);
+
+  const retry = useCallback(() => {
+    setState('loading');
+    schedule(() => setState('success'));
+  }, [schedule]);

   return (
     <section className="card sync-card" aria-live="polite">
@@ -22,6 +45,9 @@ export function AsyncPanel() {
         <div className="sync-state error" role="alert">
           <strong>Sync failed</strong>
           <span>Check your connection and try again later.</span>
+          <button type="button" className="sync-retry" onClick={retry}>
+            Retry sync
+          </button>
         </div>
       )}
     </section>
